  'home.featured.title': { en: 'Featured Rentals', el: 'Επιλεγμένα Ενοικιαζόμενα', bg: 'Избрани Имоти', ro: 'Proprietăți Recomandate', tr: 'Öne Çıkan Kiralıklar' },
