  'home.how.title':      { en: 'How it works', el: 'Πώς λειτουργεί', bg: 'Как работи', ro: 'Cum funcționează', tr: 'Nasıl çalışır' },
  'home.how.s1_t':       { en: 'Search & compare', el: 'Αναζήτηση & σύγκριση', bg: 'Търси и сравни', ro: 'Caută și compară', tr: 'Ara ve karşılaştır' },
  'home.how.s1_d':       { en: 'Browse verified properties filtered by dates, guests and location. Every listing is real — no surprises on arrival.', el: 'Περιηγηθείτε σε επαληθευμένα καταλύματα φιλτραρισμένα κατά ημερομηνίες, επισκέπτες και τοποθεσία.', bg: 'Разгледайте проверени имоти, филтрирани по дати, гости и местоположение.', ro: 'Răsfoiți proprietăți verificate filtrate după date, oaspeți și locație.', tr: 'Tarih, misafir ve konuma göre filtrelenmiş doğrulanmış mülkleri inceleyin.' },
  'home.how.s2_t':       { en: 'Book direct & pay less', el: 'Άμεση κράτηση & εξοικονόμηση', bg: 'Резервирайте директно и спестете', ro: 'Rezervați direct și plătiți mai puțin', tr: 'Doğrudan rezervasyon yapın, daha az ödeyin' },
  'home.how.s2_d':       { en: 'No OTA platform markups. Secure Stripe checkout or bank transfer. Instant or request-based booking depending on the property.', el: 'Καμία επιπλέον χρέωση πλατφόρμας. Ασφαλής πληρωμή με Stripe ή τραπεζική μεταφορά.', bg: 'Без допълнителни такси. Сигурно плащане чрез Stripe или банков превод.', ro: 'Fără majorări de platformă. Plată securizată Stripe sau transfer bancar.', tr: 'Platform ek ücreti yok. Güvenli Stripe ödemesi veya banka transferi.' },
  'home.how.s3_t':       { en: 'Arrive & enjoy', el: 'Φτάστε & απολαύστε', bg: 'Пристигнете и се насладете', ro: 'Sosiți și bucurați-vă', tr: 'Gelin ve keyfini çıkarın' },
  'home.how.s3_d':       { en: 'Self check-in or host welcome — your call. Need anything during your stay? Message the host directly, no call centre.', el: 'Αυτόνομο check-in ή υποδοχή από τον ιδιοκτήτη — επιλογή σας.', bg: 'Самостоятелно настаняване или посрещане от собственика — ваш избор.', ro: 'Check-in autonom sau primire de la proprietar — alegerea dvs.', tr: 'Kendi başına giriş veya ev sahibi karşılaması — sizin tercihiniz.' },
  'home.hl.badge':       { en: 'The Villa Experience', el: 'Η Βιλα Εμπειρία', bg: 'Изживяването на Вилата', ro: 'Experiența Vilei', tr: 'Villa Deneyimi' },
  'home.hl.title':       { en: 'Everything for a perfect Greek summer', el: 'Όλα για έναν τέλειο ελληνικό καλοκαίρι', bg: 'Всичко за перфектното гръцко лято', ro: 'Tot pentru un vară grecesc perfect', tr: 'Mükemmel bir Yunan yazı için her şey' },
  'home.hl.desc':        { en: 'Set within a lush private garden in Keramoti, this villa is designed for unforgettable stays. From alfresco dinners under the stars to morning workouts in your private gym — every detail is taken care of.', el: 'Χτισμένη μέσα σε ένα καταπράσινο ιδιωτικό κήπο στο Κεραμωτί, η βίλα είναι σχεδιασμένη για αξέχαστες διαμονές. Από γεύματα κάτω από τα αστέρια μέχρι πρωινή γυμναστική στο ιδιωτικό γυμναστήριο.', bg: 'Намираща се в буен частен градина в Керамоти, тази вила е проектирана за незабравими престои. От вечери на открито под звездите до сутрешни тренировки в частния фитнес.', ro: 'Amplasată într-o grădină privată luxuriantă în Keramoti, această vilă este concepută pentru șederi de neuitat. De la cine în aer liber sub stele până la antrenamente matinale în sala de sport privată.', tr: 'Keramoti\'deki yemyeşil özel bahçesinde yer alan bu villa, unutulmaz konaklamalar için tasarlanmıştır. Yıldızlar altında açık hava yemeklerinden özel spor salonunuzda sabah egzersizlerine kadar her detay düşünülmüştür.' },
  'home.hl.cta':         { en: 'View Villa & Book', el: 'Δείτε την Βίλα & Κάντε Κράτηση', bg: 'Вижте Вилата & Резервирайте', ro: 'Vedeți Vila și Rezervați', tr: 'Villayı Görün ve Rezervasyon Yapın' },
  'home.hl.beach':       { en: 'Beach access', el: 'Πρόσβαση σε παραλία', bg: 'Достъп до плаж', ro: 'Acces la plajă', tr: 'Plaj erişimi' },
  'home.hl.garden':      { en: 'Private garden', el: 'Ιδιωτικός κήπος', bg: 'Частна градина', ro: 'Grădină privată', tr: 'Özel bahçe' },
  'home.hl.kitchen':     { en: 'Outdoor kitchen', el: 'Εξωτερική κουζίνα', bg: 'Открита кухня', ro: 'Bucătărie exterior', tr: 'Dış mutfak' },
